import json, sys
from collections import defaultdict

users_by_ip = defaultdict(set)
fails_by_ip = defaultdict(int)

for line in open(sys.argv[1], encoding="utf-8"):
    e = json.loads(line)
    if e["result"] == "failure":
        users_by_ip[e["ip"]].add(e["user"])
        fails_by_ip[e["ip"]] += 1

for ip, users in sorted(users_by_ip.items(), key=lambda kv: -len(kv[1])):
    if len(users) >= 20:
        print(f"{ip}: {len(users)} users, {fails_by_ip[ip]} failures")

